    <title>Notification Preferences</title>
    <style>
        :root {
            --bg-color: #121212;
            --surface-color: #1e1e1e;
            --text-primary: #ffffff;
            --text-secondary: #b0b0b0;
            --accent-color: #bb86fc;
            --accent-hover: #d7b7fd;
            --focus-ring: #03dac6;
            --border-color: #333333;
        }

        body {
            margin: 0;
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
            background-color: var(--bg-color);
            color: var(--text-primary);
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
        }

        .container {
            background-color: var(--surface-color);
            padding: 2rem;
            border-radius: 8px;
            box-shadow: 0 4px 20px rgba(0, 0, 0, 0.5);
            width: 100%;
            max-width: 400px;
        }

        h1 {
            font-size: 1.5rem;
            margin-bottom: 1.5rem;
            color: var(--accent-color);
        }

        .form-field {
            margin-bottom: 1.5rem;
        }

        fieldset {
            border: none;
            padding: 0;
            margin: 0;
        }

        legend {
            font-size: 1.1rem;
            font-weight: 600;
            margin-bottom: 1rem;
            color: var(--text-primary);
        }

        .radio-option {
            display: flex;
            align-items: center;
            margin-bottom: 0.75rem;
            cursor: pointer;
            padding: 0.5rem;
            border-radius: 4px;
            transition: background-color 0.2s;
        }

        .radio-option:hover {
            background-color: rgba(255, 255, 255, 0.05);
        }

        input[type="radio"] {
            appearance: none;
            background-color: transparent;
            margin: 0 0.75rem 0 0;
            font: inherit;
            color: var(--accent-color);
            width: 1.25rem;
            height: 1.25rem;
            border: 2px solid var(--accent-color);
            border-radius: 50%;
            display: grid;
            place-content: center;
            cursor: pointer;
        }

        input[type="radio"]::before {
            content: "";
            width: 0.65rem;
            height: 0.65rem;
            border-radius: 50%;
            transform: scale(0);
            transition: 120ms transform ease-in-out;
            box-shadow: inset 1rem 1rem var(--accent-color);
        }

        input[type="radio"]:checked::before {
            transform: scale(1);
        }

        input[type="radio"]:focus {
            outline: 2px solid var(--focus-ring);
            outline-offset: 2px;
        }

        label {
            cursor: pointer;
            flex: 1;
            color: var(--text-secondary);
        }

        input[type="radio"]:checked + label {
            color: var(--text-primary);
            font-weight: 500;
        }

        button[type="submit"] {
            background-color: var(--accent-color);
            color: #000;
            border: none;
            padding: 0.75rem 1.5rem;
            font-size: 1rem;
            font-weight: 600;
            border-radius: 4px;
            cursor: pointer;
            width: 100%;
            transition: background-color 0.2s, transform 0.1s;
        }

        button[type="submit"]:hover {
            background-color: var(--accent-hover);
        }

        button[type="submit"]:active {
            transform: scale(0.98);
        }

        button[type="submit"]:focus {
            outline: 2px solid var(--focus-ring);
            outline-offset: 2px;
        }

        /* Forced Colors support */
        @media (forced-colors: active) {
            input[type="radio"] {
                border: 2px solid ButtonBorder;
            }
            input[type="radio"]:checked::before {
                background-color: Highlight;
                box-shadow: none;
            }
            button[type="submit"] {
                border: 1px solid ButtonBorder;
            }
        }
    </style>
</head>
<body>
    <div id="root"></div>

    <script type="module">
        import { h, render } from 'https://esm.sh/preact';
        import { useState } from 'https://esm.sh/preact/hooks';
        import htm from 'https://esm.sh/htm';

        const html = htm.bind(h);

        const RadioOption = ({ id, name, value, label, checked, onChange }) => {
            return html`
                <div class="radio-option">
                    <input 
                        type="radio" 
                        id=${id} 
                        name=${name} 
                        value=${value} 
                        checked=${checked} 
                        onChange=${onChange}
                        required
                    />
                    <label for=${id}>${label}</label>
                </div>
            `;
        };

        const App = () => {
            const [preference, setPreference] = useState('');

            const handleSubmit = (e) => {
                e.preventDefault();
                alert(`You preferred: ${preference}`);
            };

            const options = [
                { id: 'email', value: 'Email', label: 'Email' },
                { id: 'sms', value: 'SMS', label: 'SMS' },
                { id: 'push', value: 'Push Notifications', label: 'Push Notifications' }
            ];

            return html`
                <main class="container">
                    <h1>Settings</h1>
                    <form onSubmit=${handleSubmit}>
                        <div class="form-field">
                            <fieldset>
                                <legend>How do you prefer to receive notifications?</legend>
                                ${options.map(opt => html`
                                    <${RadioOption} 
                                        key=${opt.id}
                                        id=${opt.id}
                                        name="notification-pref"
                                        value=${opt.value}
                                        label=${opt.label}
                                        checked=${preference === opt.value}
                                        onChange=${(e) => setPreference(e.target.value)}
                                    />
                                `)}
                            </fieldset>
                        </div>
                        <button type="submit">Save preferences</button>
                    </form>
                </main>
            `;
        };

        render(html`<${App} />`, document.getElementById('root'));
    </script>
</body>
</html>
